// Function แบ่งข้อมูลสินค้า master เป็นชุดย่อยเพื่อลดขนาด transaction ตอน seed
const chunkArray = <T>(items: T[], size: number): T[][] => {
  const chunks: T[][] = [];

  for (let index = 0; index < items.length; index += size) {
    chunks.push(items.slice(index, index + size));
  }

  return chunks;
};

// Function seed ข้อมูล master_product จาก master product list ลง DB
export async function seedMasterProducts(prisma: PrismaClient): Promise<void> {
  // const batches = chunkArray(masterProductSeedData, 100);
  const batches = chunkArray(masterProductSeedData, 25);

  for (const batch of batches) {
    const operations = batch.map((item) => {
      const { id, ...data } = item;

      return prisma.masterProduct.upsert({
        where: { id },
        create: { id, ...data },
        update: data,
      });
    });

    await prisma.$transaction(operations);
  }

  console.info(
    `[seed] master_product completed: ${masterProductSeedData.length} records`,
  );
}
